function UIActionPointSelectBossBtn:OnClickBtn()
    local unlocked, desc = AnnihilationUtils.CheckAnnihilationBossUnlocked(self.activityPrefabId, self.activityContentId, self.bossTypeId)
    if not unlocked then
        if not string.isEmpty(desc) then
            GameUtils.Toast(desc)
        end
        return
    end

    if isNotNull(self.callback) then
        self.callback(self.activityPrefabId, self.activityContentId, self.bossTypeId)
    end
end

